<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/classes/GreenPortalDatabase.php';require_once dirname(__DIR__).'/classes/ContentService.php';
$e=GreenPortalDatabase::env();$p=GreenPortalDatabase::connect($e,'gatlas_dbp','GPT');$user=(int)$p->query("SELECT codusuario FROM usuarios WHERE ativo=1 ORDER BY codusuario LIMIT 1")->fetchColumn();if($user<=0)throw new RuntimeException('Usuário ativo não encontrado.');$key='TEST_CONTENT_189_'.date('YmdHis').'_'.bin2hex(random_bytes(3));
$s=new ContentService($p);$doc=$s->createDocument(['chave_idempotencia'=>$key,'codigo'=>$key,'titulo'=>'Teste Green Content','tipo_documento'=>'GED'],$user);$s->createVersion($doc,['chave_idempotencia'=>$key.'_V1','nome_arquivo'=>'teste.txt','mime_type'=>'text/plain','hash_sha256'=>hash('sha256',$key.'1'),'storage_key'=>'tenant/'.$key.'/1'],$user);$v2=$s->createVersion($doc,['chave_idempotencia'=>$key.'_V2','nome_arquivo'=>'teste-v2.txt','mime_type'=>'text/plain','hash_sha256'=>hash('sha256',$key.'2'),'storage_key'=>'tenant/'.$key.'/2'],$user);$duplicate=$s->createVersion($doc,['chave_idempotencia'=>$key.'_V2','nome_arquivo'=>'teste-v2.txt','mime_type'=>'text/plain','hash_sha256'=>hash('sha256',$key.'2'),'storage_key'=>'tenant/'.$key.'/2'],$user);$instance=$s->submitForApproval($doc,$user);$s->approve($doc,$user,'Teste funcional de homologação P2');$document=$s->find($doc);$versions=$s->versions($doc);$hist=(int)$p->query('SELECT COUNT(*) FROM workflow_historico WHERE codinstancia='.(int)$instance)->fetchColumn();$audit=(int)$p->query("SELECT COUNT(*) FROM logs_auditoria WHERE transacao='ContentService' AND registro_id='".(int)$doc."'")->fetchColumn();$ok=$document['status']==='APROVADO'&&count($versions)===2&&$hist===2&&$audit>=4&&$duplicate===$v2;
$result=['ok'=>$ok,'documento'=>$doc,'status'=>$document['status'],'versoes'=>count($versions),'versionamento_idempotente'=>$duplicate===$v2,'workflow_instancia'=>$instance,'historico'=>$hist,'auditoria'=>$audit];$p->prepare('DELETE FROM workflow_historico WHERE codinstancia=:id')->execute(['id'=>$instance]);$p->prepare('DELETE FROM workflow_instancias WHERE codinstancia=:id')->execute(['id'=>$instance]);$p->prepare('DELETE FROM content_versions WHERE coddocumento=:id')->execute(['id'=>$doc]);$p->prepare('DELETE FROM content_documents WHERE coddocumento=:id')->execute(['id'=>$doc]);echo json_encode($result,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;
